*{box-sizing:border-box}body{margin:0;background:#0a1330;color:#fff;font-family:"Baloo 2","Segoe UI",Arial,sans-serif;padding:24px}#page{max-width:1200px;margin:auto}header{display:flex;align-items:center;gap:20px;margin-bottom:22px;flex-wrap:wrap}header img{height:70px}h1{font-size:30px;margin:0}header p{color:#a9b0cc;margin:4px 0}.tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}.tab,.btn{border:0;border-radius:9px;padding:10px 16px;font:700 15px "Baloo 2";cursor:pointer;color:#fff;background:#2e5cf0}.tab{background:#141c40;border:1px solid #30385f;border-radius:999px}.tab.active{background:#e97126;border-color:#e97126}.tab.add,.btn.success{background:#298f5b}.btn.danger{background:#a93f52}.btn.secondary{background:#3a4066}.toolbar{background:#141c40;border-radius:14px;padding:14px;display:flex;gap:10px;margin-bottom:18px}.toolbar input{padding:10px 13px;border:0;border-radius:8px;font:inherit;flex:1}.variables,.agendaBox{background:#111a3b;border:1px solid #30385f;border-radius:14px;padding:16px;margin-bottom:22px}.tagRow{display:grid;grid-template-columns:minmax(170px,220px) 1fr auto;gap:10px;align-items:center;margin-top:9px}.tagCode,.monthResult{background:#0a1330;color:#ffd48a;border-radius:7px;padding:7px 9px;font-family:Consolas,monospace}.tagInfo{font-size:13px;color:#c6cbe0}.copyTag{padding:7px 11px}.monthDemo{display:flex;gap:8px;align-items:center;margin-top:12px;flex-wrap:wrap}.monthDemo select{padding:7px;border:0;border-radius:7px;font:inherit}.agendaTabs{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0}.agendaTab{background:#202951;border:0;color:#fff;border-radius:999px;padding:8px 14px;font-weight:700;cursor:pointer}.agendaTab.active{background:#e97126}.agendaTools{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px}.agendaInfo{font-size:12px;color:#8fd3ff;margin-left:auto;align-self:center}.agendaList{display:grid;gap:7px;max-height:420px;overflow:auto}.agendaEvent{display:grid;grid-template-columns:30px 150px 1fr;gap:12px;align-items:center;background:#0d1535;border-radius:9px;padding:9px 12px}.agendaCheck{width:20px;height:20px}.agendaDate{color:#ffd48a;font-weight:800}.agendaTitle{font-weight:700}.agendaMeta{font-size:12px;color:#a9b0cc}.card{background:#141c40;border-radius:16px;padding:20px;margin-bottom:16px}.card.priority{border:2px solid #e97126}.cardHead{display:flex;justify-content:space-between;gap:15px;align-items:flex-start}.category{display:inline-block;background:#e8bed4;color:#25142d;border-radius:999px;padding:3px 10px;font-size:12px;font-weight:800;margin-bottom:6px}h2{font-size:22px;margin:0}.status,.note,.message{font-size:12px;color:#a9b0cc}.priorityText{display:inline-block;background:#e97126;color:#fff;border-radius:999px;padding:4px 10px;font-size:12px;font-weight:800;margin-top:5px}.meta{display:flex;gap:10px;flex-wrap:wrap;margin:8px 0 14px}.meta input{padding:7px 9px;border:0;border-radius:7px;font:inherit}.params{background:#10183a;border-radius:10px;padding:12px;margin-bottom:12px}.paramGrid{display:grid;grid-template-columns:1fr 1fr;gap:10px}.paramGrid input{display:block;width:100%;margin-top:4px;padding:9px;border:0;border-radius:7px;font:inherit}.mailSubject,.mailBody{width:100%;border:0;border-radius:9px;padding:12px;font:15px Arial,sans-serif;color:#111}.mailSubject{font-weight:700;margin-bottom:10px}.mailBody{min-height:250px;resize:vertical;margin-bottom:10px}.previewBox{min-height:250px;background:#fff;color:#111;border-radius:10px;padding:16px;font:15px/1.5 Arial,sans-serif;margin-bottom:10px}.previewBox .subjectPreview{font-weight:700;border-bottom:1px solid #ddd;padding-bottom:10px;margin-bottom:12px}.modeBar,.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}.modeBar button{padding:7px 12px}.history{background:#0d1535;border-radius:10px;padding:12px 14px;margin:8px 0 14px}.history ul{padding-left:20px;color:#c6cbe0}.historyContact{color:#fff}.modalBack{position:fixed;inset:0;background:#0009;display:none;align-items:center;justify-content:center;padding:20px;z-index:10}.modal{background:#141c40;border-radius:16px;padding:22px;width:min(700px,100%);max-height:90vh;overflow:auto}.form{display:grid;gap:10px}.form input,.form select,.form textarea{width:100%;padding:11px;border:0;border-radius:8px;font:inherit}.form textarea{min-height:200px}.modalActions{display:flex;gap:10px;justify-content:flex-end}.empty{background:#141c40;padding:25px;border-radius:14px;color:#a9b0cc}@media(max-width:650px){body{padding:12px}.agendaEvent{grid-template-columns:28px 1fr}.agendaDate{grid-column:2}.agendaEvent>div:last-child{grid-column:2}.agendaInfo{width:100%;margin-left:0}.paramGrid{grid-template-columns:1fr}.tagRow{grid-template-columns:1fr}.toolbar{flex-direction:column}}
