<body><div id="page">
<header><img src="../agenda/img/logo-etabli.svg" alt="L'Établi Ludique"><div><h1>📧 Gestion des mails</h1><p>Mails prêts à copier dans TextBlaze, avec balises dynamiques, paramètres et historique.</p></div></header>
<div class="tabs" id="tabs"></div>
<div class="toolbar"><input id="search" type="search" placeholder="Rechercher un mail…"><button class="btn" id="add">➕ Ajouter un mail</button></div>
<section class="agendaBox"><h2>📅 Événements à venir</h2><p class="note">Liste chronologique. Choisis Commune, LEL ou LRL, puis sélectionne les événements à copier.</p><div class="agendaTabs" id="agendaTabs"></div><div class="agendaTools"><button class="btn secondary" id="selectAll">☑️ Tout sélectionner</button><button class="btn secondary" id="deselectAll">☐ Tout désélectionner</button><button class="btn success" id="copySelected">📋 Copier la sélection</button><button class="btn" id="copyAll">📋 Copier tout en brut</button><span class="agendaInfo" id="agendaInfo"></span></div><div class="agendaList" id="agendaList"></div></section>
<section class="variables"><p><strong>🏷️ Balises disponibles</strong></p><div class="tagRow"><span class="tagCode">{mois}</span><span class="tagInfo">Mois actuel en toutes lettres.</span><button class="btn copyTag" data-tag="{mois}">📋 Copier</button></div><div class="monthDemo"><strong>Tester :</strong><select id="monthDemo"></select><span class="monthResult" id="monthResult"></span></div><div class="tagRow"><span class="tagCode">{4animationsLEL}</span><span class="tagInfo">Les 4 prochaines animations LEL avec 📅 date, 🕒 horaire et 📍 lieu.</span><button class="btn copyTag" data-tag="{4animationsLEL}">📋 Copier</button></div><div class="tagRow"><span class="tagCode">{2animationsLEL}</span><span class="tagInfo">Les 2 prochaines animations LEL avec 📅 date, 🕒 horaire et 📍 lieu.</span><button class="btn copyTag" data-tag="{2animationsLEL}">📋 Copier</button></div><div class="tagRow"><span class="tagCode">{champ1}</span><span class="tagInfo">Paramètre 1 du modèle.</span><button class="btn copyTag" data-tag="{champ1}">📋 Copier</button></div><div class="tagRow"><span class="tagCode">{champ2}</span><span class="tagInfo">Paramètre 2 du modèle.</span><button class="btn copyTag" data-tag="{champ2}">📋 Copier</button></div></section>
<div id="list">Chargement…</div></div>
<div class="modalBack" id="modal"><div class="modal"><h2>➕ Ajouter un mail</h2><div class="form"><input id="newTitle" placeholder="Nom du modèle de mail"><select id="newCategory"></select><input id="newSubject" placeholder="Objet du mail"><input id="newChamp1" placeholder="Paramètre 1 — {champ1}"><input id="newChamp2" placeholder="Paramètre 2 — {champ2}"><textarea id="newBody" placeholder="Texte du mail"></textarea><div class="modalActions"><button class="btn secondary" id="cancel">Annuler</button><button class="btn success" id="create">Créer le mail</button></div></div></div></div>
<script>
const PATH="mails.json",GITHUB_PATH="communication/mails.json",AGENDA_PATH="../agenda/agenda.json",AGENDA_LOCAL_PATH="../../agenda/agenda.json",OWNER="bonnardadrien51",REPO="AfficheLEL-LRL";
let data={categories:[],mails:[]},agenda=[],fileSha="",activeCategory="",agendaMode="commun",selectedAgenda=new Set();
const token=()=>localStorage.getItem("gh_token")||"";const esc=s=>String(s??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/\"/g,"&quot;");const $=id=>document.getElementById(id);
async function load(){const r=await fetch(PATH+"?t="+Date.now());if(!r.ok)throw Error("Chargement impossible");data=await r.json();data.categories=data.categories||[];data.mails=(data.mails||[]).map(m=>({...m,historique:Array.isArray(m.historique)?m.historique:[],frequence_mois:Number(m.frequence_mois)||6,champ1:m.champ1||"",champ2:m.champ2||""}));try{const a=await fetch(AGENDA_LOCAL_PATH+"?t="+Date.now());if(a.ok){const j=await a.json();agenda=Array.isArray(j.events)?j.events:[]}}catch(e){}activeCategory=data.categories[0]||"";const g=await fetch(`https://api.github.com/repos/${OWNER}/${REPO}/contents/${GITHUB_PATH}`);if(g.ok)fileSha=(await g.json()).sha;renderTabs();fillCategories();initMonths();renderAgenda();render()}
function renderTabs(){const t=$("tabs");t.innerHTML="";data.categories.forEach(c=>{const b=document.createElement("button");b.type="button";b.className="tab"+(c===activeCategory?" active":"");b.textContent=c;b.addEventListener("click",()=>setCat(c));t.appendChild(b)});const add=document.createElement("button");add.type="button";add.className="tab add";add.textContent="➕ Ajouter une catégorie";add.addEventListener("click",addCategory);t.appendChild(add)}
function setCat(c){activeCategory=c;renderTabs();render()}
function fillCategories(){$("newCategory").innerHTML=data.categories.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join("")}
async function addCategory(){const c=prompt("Nom de la nouvelle catégorie");if(!c||!c.trim())return;const n=c.trim();if(data.categories.includes(n)){setCat(n);return}data.categories.push(n);activeCategory=n;fillCategories();renderTabs();render();await saveData()}
function initMonths(){const s=$("monthDemo"),months=["janvier","février","mars","avril","mai","juin","juillet","août","septembre","octobre","novembre","décembre"];s.innerHTML=months.map((m,i)=>`<option value="${i}">${m}</option>`).join("");s.value=new Date().getMonth();s.onchange=()=>$("monthResult").textContent=months[Number(s.value)];s.onchange()}
function eventDate(e){return new Date(e.start).toLocaleDateString("fr-FR",{weekday:"long",day:"numeric",month:"long",year:"numeric"})}
function eventHours(e){const s=new Date(e.start),f=e.end?new Date(e.end):null;if(!f||Number.isNaN(f.getTime()))return s.toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit"});return `${s.toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit"})} à ${f.toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit"})}`}
function eventName(e){return e.campaign?.titre||e.title||"Événement"}function eventPlace(e){return e.campaign?.lieu||e.location||""}function isLEL(e){return ["Partenaire","Animation","Marché / Expo"].includes(e.calendar)}function isLRL(e){return ["Soirée au chapeau","Soirée adhérents"].includes(e.calendar)}
function agendaEvents(){const now=new Date();let es=agenda.filter(e=>{const d=new Date(e.start||"");return !Number.isNaN(d.getTime())&&d>=now});if(agendaMode==="lel")es=es.filter(isLEL);if(agendaMode==="lrl")es=es.filter(isLRL);return es.sort((a,b)=>new Date(a.start)-new Date(b.start))}
function eventKey(e){return e.uid||e.id||e.iCalUID||`${e.start}|${eventName(e)}`}function eventRaw(e){return `${eventName(e)}\n\n📅 ${eventDate(e)}\n🕒 ${eventHours(e)}${eventPlace(e)?`\n📍 ${eventPlace(e)}`:""}`}
function renderAgenda(){const tabs=$("agendaTabs");tabs.innerHTML="";[["commun","📅 Commune"],["lel","🧰 LEL"],["lrl","🎲 LRL"]].forEach(([k,n])=>{const b=document.createElement("button");b.type="button";b.className="agendaTab"+(k===agendaMode?" active":"");b.textContent=n;b.addEventListener("click",()=>{agendaMode=k;renderAgenda()});tabs.appendChild(b)});const es=agendaEvents(),list=$("agendaList");list.innerHTML=es.length?es.map(e=>{const k=eventKey(e);return `<label class="agendaEvent"><input class="agendaCheck" type="checkbox" data-key="${esc(k)}" ${selectedAgenda.has(k)?"checked":""}><div class="agendaDate">📅 ${esc(eventDate(e))}<br><span class="agendaMeta">🕒 ${esc(eventHours(e))}</span></div><div><div class="agendaTitle">${esc(eventName(e))}</div><div class="agendaMeta">${eventPlace(e)?`📍 ${esc(eventPlace(e))}`:""} ${esc(e.calendar||"")}</div></div></label>`}).join(""):"<div class='empty'>Aucun événement à venir dans cette vue.</div>";document.querySelectorAll(".agendaCheck").forEach(c=>c.addEventListener("change",()=>{c.checked?selectedAgenda.add(c.dataset.key):selectedAgenda.delete(c.dataset.key);updateAgendaInfo()}));updateAgendaInfo()}
function updateAgendaInfo(){const n=document.querySelectorAll(".agendaCheck:checked").length;$("agendaInfo").textContent=n?`${n} sélectionné${n>1?"s":""}`:""}function setAgendaSelection(v){document.querySelectorAll(".agendaCheck").forEach(c=>{c.checked=v;v?selectedAgenda.add(c.dataset.key):selectedAgenda.delete(c.dataset.key)});updateAgendaInfo()}
async function copyAgenda(all){const es=agendaEvents().filter(e=>all||selectedAgenda.has(eventKey(e)));if(!es.length){$("agendaInfo").textContent="⚠️ Aucun événement à copier.";return}try{await navigator.clipboard.writeText(es.map(eventRaw).join("\n\n"));$("agendaInfo").textContent=`✓ ${es.length} événement${es.length>1?"s":""} copié${es.length>1?"s":""}.`}catch(e){$("agendaInfo").textContent="❌ Copie impossible."}}
function futureLEL(){return agenda.filter(e=>{const d=new Date(e.start);return !Number.isNaN(d.getTime())&&d>=new Date()&&isLEL(e)}).sort((a,b)=>new Date(a.start)-new Date(b.start))}
function animationsText(n){const es=futureLEL().slice(0,n);return es.length?es.map(e=>`• ${eventName(e)}\n📅 ${eventDate(e)}\n🕒 ${eventHours(e)}${eventPlace(e)?`\n📍 ${eventPlace(e)}`:""}`).join("\n\n"):"• Aucune prochaine animation programmée pour le moment."}
function replaceVars(text,m){const months=["janvier","février","mars","avril","mai","juin","juillet","août","septembre","octobre","novembre","décembre"];return String(text||"").replaceAll("{mois}",months[new Date().getMonth()]).replaceAll("{4animationsLEL}",animationsText(4)).replaceAll("{2animationsLEL}",animationsText(2)).replaceAll("{champ1}",m?.champ1||"").replaceAll("{champ2}",m?.champ2||"")}
function age(m){if(!m.derniere_utilisation)return null;const d=new Date(m.derniere_utilisation),n=new Date();return Math.max(0,(n.getFullYear()-d.getFullYear())*12+n.getMonth()-d.getMonth())}function priority(m){const a=age(m);return a===null||a>=m.frequence_mois}function ageText(m){const a=age(m);if(a===null)return "⚠️ Jamais utilisé";if(a>=m.frequence_mois)return `⚠️ À utiliser — dernière utilisation il y a ${a} mois`;return a===0?"Utilisé ce mois-ci":`Utilisé il y a ${a} mois`}
function filtered(){const q=$("search").value.toLowerCase().trim();return data.mails.filter(m=>m.categorie===activeCategory&&(!q||[m.titre,m.objet,m.corps,m.champ1,m.champ2].join(" ").toLowerCase().includes(q))).sort((a,b)=>Number(priority(b))-Number(priority(a))||new Date(a.derniere_utilisation||"1900-01-01")-new Date(b.derniere_utilisation||"1900-01-01"))}
function render(){const list=$("list"),ms=filtered();if(!ms.length){list.innerHTML='<div class="empty">Aucun modèle dans cette catégorie.</div>';return}list.innerHTML=ms.map(card).join("")}
function card(m){const hist=(m.historique||[]).slice().sort((a,b)=>new Date(b.date)-new Date(a.date));return `<article class="card ${priority(m)?"priority":""}"><div class="cardHead"><div><span class="category">${esc(m.categorie)}</span><h2>${esc(m.titre)}</h2><span class="priorityText">${esc(ageText(m))}</span></div><span class="status">${m.derniere_utilisation?`Dernière utilisation : ${esc(m.derniere_utilisation)}`:"Jamais utilisé"}</span></div><div class="meta"><label>Fréquence <input type="number" min="1" value="${m.frequence_mois}" data-action="freq" data-id="${esc(m.id)}"> mois</label></div><div class="params"><div class="paramGrid"><label>Paramètre 1<input value="${esc(m.champ1)}" data-action="param" data-field="champ1" data-id="${esc(m.id)}"></label><label>Paramètre 2<input value="${esc(m.champ2)}" data-action="param" data-field="champ2" data-id="${esc(m.id)}"></label></div></div><input class="mailSubject" value="${esc(m.objet||"")}" data-action="field" data-field="objet" data-id="${esc(m.id)}"><div class="modeBar"><button class="btn modeBtn" data-mode="raw" data-id="${esc(m.id)}">✏️ Modifier</button><button class="btn secondary modeBtn" data-mode="preview" data-id="${esc(m.id)}">👁️ Prévisualisation</button><span class="modeInfo">Les balises sont remplacées lors de la copie.</span></div><textarea class="mailBody" id="body-${esc(m.id)}" data-action="body" data-id="${esc(m.id)}">${esc(m.corps||"")}</textarea><div id="preview-${esc(m.id)}" class="previewBox" style="display:none"></div><div class="history"><strong>📜 Historique des utilisations</strong>${hist.length?`<ul>${hist.map(h=>`<li>${esc(h.date)} — <span class="historyContact">${esc(h.contact||"sans contact")}</span>${h.email?` — ${esc(h.email)}`:""}${h.note?` — ${esc(h.note)}`:""}</li>`).join("")}</ul>`:'<div class="note">Aucune utilisation enregistrée.</div>'}</div><div class="actions"><button class="btn actionBtn" data-action="copy" data-id="${esc(m.id)}">📋 Copier pour TextBlaze</button><button class="btn success actionBtn" data-action="use" data-id="${esc(m.id)}">➕ Ajouter une utilisation</button><button class="btn secondary actionBtn" data-action="rename" data-id="${esc(m.id)}">✏️ Renommer</button><button class="btn danger actionBtn" data-action="delete" data-id="${esc(m.id)}">🗑️ Supprimer</button></div></article>`}
function find(id){return data.mails.find(m=>m.id===id)}async function changeField(id,k,v){const m=find(id);if(m){m[k]=v;await saveData()}}async function changeParam(id,k,v){const m=find(id);if(m){m[k]=v;await saveData()}}async function changeFreq(id,v){const m=find(id);if(m){m.frequence_mois=Math.max(1,Number(v)||6);await saveData();render()}}
async function renameMail(id){const m=find(id);if(!m)return;const n=prompt("Nouveau nom du modèle :",m.titre);if(n&&n.trim()&&n.trim()!==m.titre){m.titre=n.trim();await saveData();render()}}
async function deleteMail(id){const m=find(id);if(!m)return;if(!confirm(`Supprimer définitivement le modèle « ${m.titre} » ?\n\nSon historique d'utilisation sera également supprimé.`))return;data.mails=data.mails.filter(x=>x.id!==id);await saveData();render()}
function showMode(id,mode){const m=find(id),b=$("body-"+id),p=$("preview-"+id);if(!m||!b||!p)return;if(mode==="preview"){p.innerHTML='<div class="subjectPreview">Objet : '+esc(replaceVars(m.objet,m))+'</div>'+esc(replaceVars(m.corps,m)).replace(/\n/g,"<br>");b.style.display="none";p.style.display="block"}else{b.style.display="block";p.style.display="none"}}
async function copyMail(id){const m=find(id);if(!m)return;const text=`Objet : ${replaceVars(m.objet,m)}\n\n${replaceVars(m.corps,m)}`;try{await navigator.clipboard.writeText(text);alert("Mail copié avec les balises remplacées.")}catch(e){alert("Impossible de copier le mail.")}}
async function recordUse(id){const m=find(id);if(!m)return;const date=prompt("Date de l’utilisation (AAAA-MM-JJ) :",new Date().toISOString().slice(0,10));if(!date)return;const contact=prompt("Contact (facultatif) :","")||"";const email=prompt("Email (facultatif) :","")||"";const note=prompt("Note (facultatif) :","")||"";m.historique=m.historique||[];m.historique.push({date,contact,email,note});m.derniere_utilisation=date;await saveData();render()}
function addMail(){$("modal").style.display="flex"}async function createMail(){const m={id:"mail-"+Date.now(),categorie:$("newCategory").value,titre:$("newTitle").value.trim()||"Nouveau mail",objet:$("newSubject").value,corps:$("newBody").value,champ1:$("newChamp1").value,champ2:$("newChamp2").value,frequence_mois:6,derniere_utilisation:null,historique:[]};data.mails.push(m);activeCategory=m.categorie;$("modal").style.display="none";["newTitle","newSubject","newChamp1","newChamp2","newBody"].forEach(id=>$(id).value="");renderTabs();render();await saveData()}
async function saveData(){if(!token()){console.warn("Token GitHub absent : modifications locales non synchronisées.");return false}try{const r=await fetch(`https://api.github.com/repos/${OWNER}/${REPO}/contents/${GITHUB_PATH}`,{method:"PUT",headers:{Authorization:`Bearer ${token()}`,Accept:"application/vnd.github+json","Content-Type":"application/json"},body:JSON.stringify({message:"Mise à jour des modèles de mails",content:btoa(unescape(encodeURIComponent(JSON.stringify(data,null,2)))),sha:fileSha})});if(!r.ok){alert("Erreur de sauvegarde GitHub : "+await r.text());return false}fileSha=(await r.json()).content.sha;return true}catch(e){alert("Erreur de sauvegarde : "+e);return false}}
function bind(){$("selectAll").onclick=()=>setAgendaSelection(true);$("deselectAll").onclick=()=>setAgendaSelection(false);$("copySelected").onclick=()=>copyAgenda(false);$("copyAll").onclick=()=>copyAgenda(true);$("add").onclick=addMail;$("cancel").onclick=()=>$("modal").style.display="none";$("create").onclick=createMail;$("search").oninput=render;document.querySelectorAll(".copyTag").forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(b.dataset.tag);b.textContent="✓ Copié";setTimeout(()=>b.textContent="📋 Copier",1200)}catch(e){}});$("modal").onclick=e=>{if(e.target.id==="modal")e.currentTarget.style.display="none"};document.addEventListener("click",async e=>{const btn=e.target.closest(".actionBtn,.modeBtn");if(!btn)return;const id=btn.dataset.id;if(btn.classList.contains("modeBtn"))return showMode(id,btn.dataset.mode);switch(btn.dataset.action){case"copy":return copyMail(id);case"use":return recordUse(id);case"rename":return renameMail(id);case"delete":return deleteMail(id)}});document.addEventListener("change",async e=>{const el=e.target,id=el.dataset.id;if(!id)return;if(el.dataset.action==="freq")return changeFreq(id,el.value);if(el.dataset.action==="param")return changeParam(id,el.dataset.field,el.value);if(el.dataset.action==="field")return changeField(id,el.dataset.field,el.value);if(el.dataset.action==="body")return changeField(id,"corps",el.value)})}
bind();load().catch(e=>{$("list").innerHTML='<div class="empty">Erreur de chargement : '+esc(e.message)+"</div>"});
</script></body></html>